contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function driving c; caller provides an amount to fund c and two addresses:
    // ownerCaller should be the Owner of c (the original deployer of C), otherCaller is any other address.
    // We cannot change msg.sender in solidity here, so we simulate by observing behavior from this contract
    // after c has been funded and then withdraw is invoked by this contract. The distinguishing behavior
    // is whether withdraw succeeds only when msg.sender==Owner. To make that observable we require that
    // this contract is the Owner; the verifier will check both P and M variants by supplying instances
    // where Owner==address(this) or Owner!=address(this).

    // The function sends 'fund' wei to c, then calls withdraw and finally asserts relation between
    // address(c).balance and whether this contract is Owner (queried via c.Owner()).
    function test(uint256 fund) public payable {
        require(address(this).balance >= fund);

        // fund the contract c
        (bool sent,) = address(c).call{value: fund}("");
        require(sent);

        // call withdraw (this contract is the msg.sender for this call)
        c.withdraw();

        // If this contract is Owner, withdraw on original P will send the balance away (to Owner),
        // leaving c's balance == 0. If this contract is not Owner, withdraw on P reverts due to require and
        // thus this line would not be reached. Therefore when reached, on P it must hold that
        // address(c).balance == 0 iff address(this) == c.Owner(). On mutant M (require removed), anyone
        // can withdraw so address(c).balance == 0 holds regardless of ownership, violating the iff.
        assert((address(c).balance == 0) == (address(this) == c.Owner()));
    }

    // allow contract to receive ether so test can be funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no special precondition
        bool reverted;
        try c.withdraw{value: 0}() { reverted = false; } catch { reverted = true; }   // boundary
        // In the original contract, withdraw reverts for callers who are not Owner.
        // We express that as: if msg.sender is not c.Owner(), then the call must have reverted.
        // We can read c.Owner() via its public getter and compare to msg.sender.
        assert(msg.sender == c.Owner() || reverted == true);
    }
    receive() external payable { }
}

