pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address caller (potential attacker) and an amount to send via Command
    function testFuzz_property(address caller, uint256 sendAmt) public {
        // keep sendAmt within reasonable gas/ETH limits
        sendAmt = bound(sendAmt, 0, 1 ether);
        // ensure caller is not the Owner (the deployer in setUp) to exercise non-owner behavior
        vm.assume(caller != address(this));

        // fund caller so they can send ETH through Command
        vm.deal(caller, sendAmt);

        // prepare calldata for a benign call: call to address(0) with empty data
        // use a helper benign callee so the call itself succeeds (EOA would also succeed, but we use a contract to be explicit)
        BenignReceiver ben = new BenignReceiver();

        // initial contract balance: top it up so withdraw would have funds to send
        // fund the contract from this test contract (which is Owner) so Owner balance increases
        uint256 initialFund = 0.5 ether;
        vm.deal(address(this), initialFund);
        // from Owner (this) send ETH to contract
        vm.prank(address(this));
        (bool s,) = address(c).call{value: initialFund}("");
        require(s);

        // record balance before the Command call
        uint256 before = address(c).balance;

        // Now have caller invoke Command to perform a low-level call to ben with forwarded value sendAmt
        vm.prank(caller);
        // call Command(ben.address, empty data) sending sendAmt wei
        // encode empty bytes
        bytes memory data = "";
        // perform the call; wrap in try/catch to ensure we observe outcome but not assert on it
        try c.Command{value: sendAmt}(address(ben), data) {
            // ok
        } catch {
            // ignore revert; Command may revert depending on callee behavior, but our benign receiver does not
        }

        // After Command, the property we assert: withdraw called by non-Owner must not have drained the contract.
        // We check this by comparing the contract balance to what it was before: since only Owner can withdraw,
        // a non-Owner's use of Command cannot cause the contract balance to decrease via withdraw.
        // The reference implementation enforces that only Owner can withdraw, so for any caller != Owner,
        // address(c).balance should be >= before (it may increase if Command forwarded ETH leading to transfers back into c),
        // but it must not be less than before due to a withdraw executed by a non-owner. The mutant allows non-owners
        // to trigger withdraw and thus can make balance < before for some inputs.

        uint256 after = address(c).balance;

        // Single assertion: contract balance did not decrease (i.e., non-owner could not cause a withdraw)
        assertTrue(after >= before);
    }
}

// A benign receiver that simply accepts ETH
contract BenignReceiver {
    receive() external payable {}
}

