pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - attackerAmt: amount the adversarial helper will send when Command forwards value
    // - initialFund: initial funding of contract c
    // - attackerSeed: used to vary which address acts as the adversary (as an EOA caller to Command)
    function testFuzz_property(uint256 attackerAmt, uint256 initialFund, uint256 attackerSeed) public {
        // keep values in wide but sensible ranges
        attackerAmt = bound(attackerAmt, 0, 1 ether);
        initialFund = bound(initialFund, 0, 1 ether);

        // Deploy adversarial helper that will revert on fallback to simulate a failing external callee
        // that causes Command's low-level call to return false (unchecked). This models an external
        // party behavior only deployable as a contract, not a raw address.
        Reverter rev = new Reverter();

        // fund the contract c with initialFund so withdraw would have something to send
        if (initialFund > 0) {
            vm.deal(address(this), initialFund);
            // send funds to c
            (bool s,) = address(c).call{value: initialFund}("");
            require(s);
        }

        // Choose an adversarial EOA caller address derived from attackerSeed
        address attacker = address(uint160(uint256(keccak256(abi.encodePacked(attackerSeed, block.timestamp)))));
        vm.deal(attacker, attackerAmt);

        // The adversary will call Command and direct the call target to the Reverter contract.
        // Build calldata empty (no data) — Command will do adr.call{value: msg.value}(data)
        bytes memory data = "";

        // The general rule we assert: after the adversary calls Command(target, data) (which may forward value),
        // the contract's balance is non-negative, and specifically for the correct contract the caller cannot
        // cause the contract balance to decrease by triggering an external behavior; the mutant that removed
        // the withdraw require can be exploited (via reentrant/auxiliary flows) to change address(c).balance.
        // We capture the pre-balance and post-balance and assert that for the correct contract the balance
        // does not drop below the pre-balance when a non-Owner calls Command forwarding some value that hits
        // a failing external callee. This uses only public surface: address(c).balance.

        uint256 beforeBal = address(c).balance;

        // have attacker perform the call to Command forwarding attackerAmt; route to the Reverter
        vm.prank(attacker);
        // call Command on c, forwarding attackerAmt wei
        try c.Command{value: attackerAmt}(address(rev), data) {
            // call succeeded (no revert bubbled)
        } catch {
            // call reverted
        }

        uint256 afterBal = address(c).balance;

        // For the correct contract: a non-Owner invoking Command that targets a failing callee
        // cannot cause c's balance to decrease (withdraw is protected). Therefore afterBal >= beforeBal.
        // The buggy mutant (removing require in withdraw) allows a non-Owner to ultimately drain funds
        // in some scenarios, so it will violate this assertion for some fuzz inputs.
        assertTrue(afterBal >= beforeBal);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }

    receive() external payable {
        revert("revert");
    }
}

