import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address (who will invoke Command) and an amount to send with Command
    function testFuzz_property(address caller, uint256 sendAmt) public {
        // keep sendAmt in a wide but sensible range
        sendAmt = bound(sendAmt, 0, 1 ether);

        // pick a caller that is not the Owner (Owner is deployer = address(this) at setUp)
        // fuzzed `caller` may equal address(this); if so, skip such cases so we only test non-Owners
        vm.assume(caller != address(this));

        // fund both the contract and the caller appropriately
        vm.deal(address(c), 1 ether); // give contract an initial balance
        vm.deal(caller, sendAmt);

        // prepare arbitrary calldata that does nothing (empty) — Command will low-level call target
        bytes memory emptyCalldata = "";

        // We want to route Command's adr.call through a helper that will attempt to trigger withdraw on c
        // Deploy a helper that upon receiving ETH will call c.withdraw(). This simulates an external counterparty
        // that, if withdraw can be invoked by anyone, ends up getting the contract balance forwarded to Owner.
        CallerHelper helper = new CallerHelper(address(c));

        // Now have the fuzzed caller invoke c.Command(helper, emptyCalldata) sending sendAmt
        vm.prank(caller);
        // call Command on c, forwarding sendAmt wei from caller to c which then forwards to helper
        // capture success/failure but we don't need it; the property concerns address(c).balance after this
        try c.Command{value: sendAmt}(address(helper), emptyCalldata) {
            // call returned
        } catch {
            // ignore revert — still check balance
        }

        // SINGLE assertion: for the correct reference contract C, if a non-Owner calls Command routed to a helper
        // that triggers withdraw behavior, the contract's balance must remain unchanged (only Owner can withdraw).
        // The mutant that removes the require allows some such interactions to reduce address(c).balance.
        assertTrue(address(c).balance == 1 ether);
    }
}

// Helper contract that will, when receiving ETH, attempt to invoke c.withdraw().
// This models an external party that when called by C will call back into C.
contract CallerHelper {
    C immutable target;
    constructor(address _c) { target = C(_c); }

    // receive will be invoked when C calls adr.call{value: msg.value}(...)
    receive() external payable {
        // attempt to call withdraw on the target contract
        // if withdraw is protected (reference), this call will revert or do nothing; if withdraw is unprotected (mutant),
        // it will send target's balance to Owner, changing address(target).balance.
        // We ignore success to allow continuation.
        try target.withdraw() {
            // ok
        } catch {
            // ignore
        }
    }
}

