pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: amount to send with Command, and a boolean choosing whether the callee will revert
    function testFuzz_property(uint256 amount, bool willRevert) public {
        // keep amount sensible but wide: at least 0 and <= 1e18
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial callee that either reverts or accepts
        Callee callee = new Callee(willRevert);

        // fund the caller (owner) so it can send the value in Command
        address owner = c.Owner();
        vm.deal(owner, amount);

        // call Command as Owner, sending 'amount' wei to the callee address
        // capture whether the call completed (no revert) or reverted using try/catch
        bool ok;
        vm.prank(owner);
        try c.Command{value: amount}(address(callee), abi.encodeWithSignature("ping()")) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference contract never reverts on Command because it ignores callee failure
        // We assert that c.Command did NOT revert (ok == true). This holds for the reference C for ALL inputs,
        // while the mutant (which requires success) will revert when callee reverts (willRevert == true) ---
        // thus the single assertion distinguishes them.
        assertTrue(ok);
    }
}

// adversarial callee: either always reverts on fallback/call or accepts payments
contract Callee {
    bool public willRevert;
    constructor(bool _willRevert) payable { willRevert = _willRevert; }
    fallback() external payable {
        if (willRevert) revert("revert on purpose");
    }
    receive() external payable {
        if (willRevert) revert("revert on purpose");
    }
    function ping() external payable {}
}
